from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oauth2_provider.models import AccessToken

class MicroserviceScopeAuditView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        token_hash = request.data.get("token_hash")
        caller_app = getattr(request.auth, 'application', None)
        # Restrict audit lookup to tokens provisioned for the calling application
        token_obj = AccessToken.objects.filter(
            token=token_hash,
            application=caller_app
        ).first()
        if not token_obj:
            return Response({"error": "Token record not found or unauthorized"}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            "valid": not token_obj.is_expired(),
            "client_name": token_obj.application.name,
            "granted_scopes": token_obj.scope.split(),
            "user_email": token_obj.user.email if token_obj.user else None
        }, status=status.HTTP_200_OK)
